#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int getMaximumConsecutive(vector<int>& coins) {
        sort(coins.begin(), coins.end());
        int reach = 0;
        for (int c : coins) {
            if (c <= reach + 1) {
                reach += c;
            } else {
                break;
            }
        }
        return reach + 1;
    }
};

import java.util.Arrays;

class Solution {
    public int getMaximumConsecutive(int[] coins) {
        Arrays.sort(coins);
        int reach = 0;
        for (int c : coins) {
            if (c <= reach + 1) {
                reach += c;
            } else {
                break;
            }
        }
        return reach + 1;
    }
}

/**
 * @param {number[]} coins
 * @return {number}
 */
var getMaximumConsecutive = function(coins) {
    coins.sort((a, b) => a - b);
    let reach = 0;
    for (const c of coins) {
        if (c <= reach + 1) {
            reach += c;
        } else {
            break;
        }
    }
    return reach + 1;
};
